#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

struct step {
	ll number; int totalCost;
	bool operator<(const step &other) const {
		return other.totalCost < totalCost;
	}
};

set<ll> visitedNodes;

bool isAlreadyVisited(ll c) {
	return visitedNodes.count(c) > 0;
}

step getUupper(ll n){
	ll res = 0;
	int digitsCount = 0;
	while(res < n){
		res = res * 10 + 1;
		digitsCount++;
	}
	return {res, digitsCount};
}

step getUpperLimit(ll n){
	ll res = 0;
	int digitsCount = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		digitsCount++;
	}
	ll baseRes = res;
	int baseDigits = digitsCount;
	while(res < n){
		res += baseRes;
		digitsCount += baseDigits;
	}
	return {res, digitsCount};
}

step getLowerLimit(ll n){
	ll res = 0;
	int digitsCount = 0;
	while(res * 10 + 1 <= n){
		res = res * 10 + 1;
		digitsCount++;
	}
	ll baseRes = res;
	int baseDigits = digitsCount;
	while(res + baseRes <= n){
		res += baseRes;
		digitsCount += baseDigits;
	}
	return {res, digitsCount};
}

int main() {
	ll n;
	cin >> n;

	priority_queue<step> pq;

	pq.push({n, 0});

	while(pq.top().number != 0){
		ll currentNumber = pq.top().number;
		int currentCost = pq.top().totalCost;
		pq.pop();

		if(isAlreadyVisited(currentNumber))
			continue;
		visitedNodes.insert(currentNumber);

		for (auto s : { getLowerLimit(currentNumber), getUpperLimit(currentNumber), getUupper(currentNumber) }) {
			s.totalCost += currentCost;
			s.number = abs(currentNumber - s.number);
			pq.push(s);
		}
	}

	cout << pq.top().totalCost << endl;
}
